// other structured blocks. Used for kind classification: recap/compaction
// instructions arrive as plain text, and a tool_result echoing those phrases
// (e.g. captured command output) must not trigger a false positive.
function lastMessagePromptText(content: unknown): string {
  const asStr = asString(content);
  if (asStr !== null) return asStr;
  let out = "";
  for (const block of asArray(content)) {
    const record = asRecord(block);
    if (!record) continue;
    if (record.type !== undefined && record.type !== "text") continue;
    const text = asString(record.text);
    if (text !== null) out += text;
  }
  return out;
}

// Detect whether a message is a tool-result carrier — i.e. delivers tool
// results back to the model without any new user intent text. These are
// auto-generated by the agent runtime, not typed by the user.
function isToolResultCarrier(msg: Record<string, unknown>): boolean {
  const role = asString(msg.role);
  // OpenAI / DeepSeek: dedicated "tool" role is always a carrier.
  if (role === "tool") return true;
  // Anthropic: tool results travel inside a user-role message. A pure carrier
  // has only tool_result blocks (no text blocks, no thinking blocks).
  if (role !== "user") return false;
  const blocks = asArray(msg.content);
  if (blocks.length === 0) return false;
  for (const block of blocks) {
    const b = asRecord(block);
    if (!b) continue;
    const type = asString(b.type);
    if (type !== "tool_result" && type !== "toolResult") return false;
  }
  return true;
}"}

