  try {
    const bin = atob(b64);
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    return new TextDecoder("utf-8", { fatal: false }).decode(bytes);
  } catch {
    return "";
  }
}

async function decompressResponse(events) {
  const responseEvent = events.find((e) => e.type === "response");
  const encoding = responseEvent?.headers?.["content-encoding"];
  if (!encoding) {
    return events
      .filter((e) => e.type === "response_body")
      .map((e) => b64ToText(e.data))
      .join("");
  }
  try {
    const chunks = events
      .filter((e) => e.type === "response_body" && e.data)
      .map((e) => {
        const bin = atob(e.data);
        return Uint8Array.from(bin, (c) => c.charCodeAt(0));
      });
    if (chunks.length === 0) return `[${encoding}-encoded — run \`aap parse\` for metrics]`;
    const totalLen = chunks.reduce((s, c) => s + c.length, 0);
    const merged = new Uint8Array(totalLen);
    let off = 0;
    for (const c of chunks) {
      merged.set(c, off);
      off += c.length;
    }
    const format =
      encoding === "gzip"
        ? "gzip"
        : encoding === "deflate"
          ? "deflate"
          : encoding === "br"
            ? "br"
            : "gzip";
    const ds = new DecompressionStream(format);
    const writer = ds.writable.getWriter();
    writer.write(merged);
    writer.close();
    const buf = await new Response(ds.readable).arrayBuffer();
    return new TextDecoder("utf-8", { fatal: false }).decode(buf);
  } catch {
    return `[${encoding}-encoded — run \`aap parse\` for metrics]`;
  }
