async function sessions() {
  const list = await api("/sessions");
  const filters = { provider: "", cwd: "", minReqs: 0, minCached: 0, sort: "newest" };
  let currentPage = 0;
  const PAGE = 25;

  const providers = [...new Set(list.map((s) => s.client).filter(Boolean))].sort();

  function apply() {
    let filtered = [...list];
    if (filters.provider)
      filtered = filtered.filter((s) => s.client === filters.provider);
    if (filters.cwd)
      filtered = filtered.filter((s) =>
        (s.cwd || "").toLowerCase().includes(filters.cwd.toLowerCase()),
      );
    if (filters.minReqs > 0)
      filtered = filtered.filter((s) => s.request_count >= filters.minReqs);
    if (filters.minCached > 0)
      filtered = filtered.filter((s) => {
        if (!s.input_tokens) return false;
        return (s.cached_input_tokens / s.input_tokens) * 100 >= filters.minCached;
      });
    switch (filters.sort) {
      case "oldest":
        filtered.sort(
          (a, b) => new Date(a.last_seen_at || 0) - new Date(b.last_seen_at || 0),
        );
        break;
      case "most-reqs":
        filtered.sort((a, b) => b.request_count - a.request_count);
        break;
      case "highest-cost":
        filtered.sort((a, b) => b.cost - a.cost);
        break;
      case "highest-cache":
        filtered.sort((a, b) => {
          const ar = a.input_tokens > 0 ? a.cached_input_tokens / a.input_tokens : 0;
          const br = b.input_tokens > 0 ? b.cached_input_tokens / b.input_tokens : 0;
          return br - ar;
        });
        break;
      default:
        filtered.sort(
          (a, b) => new Date(b.last_seen_at || 0) - new Date(a.last_seen_at || 0),
        );
    }
    return filtered;
  }

