        : "";

    const changed =
      filtered.length !== list.length
        ? ` <span class="muted">(${filtered.length} shown / ${list.length} total)</span>`
        : "";

    app.innerHTML = `
    <h2>Sessions (${num(list.length)})${changed}</h2>
