      const last = items[items.length - 1];
      const aggCost = items.reduce((s, r) => s + (r.cost ?? 0), 0);
      const aggLatency = items.reduce((s, r) => s + (r.latency_ms ?? 0), 0);
      const aggInput = items.reduce(
