      const aggOutput = items.reduce((s, r) => s + (r.output_tokens ?? 0), 0);
      const allToolNames = new Set();
      for (const r of items) {
        for (const tc of tcByRequest[r.id] || []) allToolNames.add(tc.name);
      }
      const toolList = [...allToolNames].slice(0, 6).join(", ");
      const overflow =
